 81→// doPushSessionsBranch pushes the sessions branch to the remote.
 82→func doPushSessionsBranch(remote, branchName string) error {
 83→	fmt.Fprintf(os.Stderr, "[entire] Pushing session logs to %s...\n", remote)
 84→
 85→	// Try pushing first
 86→	if err := tryPushSessionsCommon(remote, branchName); err == nil {
 87→		return nil
 88→	}
 89→
 90→	// Push failed - likely non-fast-forward. Try to fetch and merge.
 91→	fmt.Fprintf(os.Stderr, "[entire] Syncing with remote session logs...\n")
 92→
 93→	if err := fetchAndMergeSessionsCommon(remote, branchName); err != nil {
 94→		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync sessions: %v\n", err)
 95→		return nil // Don't fail the main push
 96→	}
 97→
 98→	// Try pushing again after merge
 99→	if err := tryPushSessionsCommon(remote, branchName); err != nil {
100→		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push sessions after sync: %v\n", err)
101→	}
102→
103→	return nil
104→}
105→
106→// tryPushSessionsCommon attempts to push the sessions branch.
107→func tryPushSessionsCommon(remote, branchName string) error {
108→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
109→	defer cancel()
110→
111→	// Use --no-verify to prevent recursive hook calls
112→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", remote, branchName)
113→	cmd.Stdin = nil // Disconnect stdin to prevent hanging in hook context
114→
115→	output, err := cmd.CombinedOutput()
116→	if err != nil {
117→		// Check if it's a non-fast-forward error (we can try to recover)
118→		if strings.Contains(string(output), "non-fast-forward") ||
119→			strings.Contains(string(output), "rejected") {
120→			return errors.New("non-fast-forward")
121→		}
122→		return fmt.Errorf("push failed: %s", output)
123→	}
124→	return nil
125→}
126→
127→// fetchAndMergeSessionsCommon fetches remote sessions and merges into local using go-git.
128→// Since session logs are append-only (unique cond-* directories), we just combine trees.
129→func fetchAndMergeSessionsCommon(remote, branchName string) error {
130→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
131→	defer cancel()
132→
133→	// Use git CLI for fetch (go-git's fetch can be tricky with auth)
134→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", remote, branchName)
135→	fetchCmd.Stdin = nil
136→	if output, err := fetchCmd.CombinedOutput(); err != nil {
137→		return fmt.Errorf("fetch failed: %s", output)
138→	}
139→
140→	repo, err := OpenRepository()
141→	if err != nil {
142→		return fmt.Errorf("failed to open git repository: %w", err)
143→	}
144→
145→	// Get local branch
146→	localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
147→	if err != nil {
148→		return fmt.Errorf("failed to get local ref: %w", err)
149→	}
150→	localCommit, err := repo.CommitObject(localRef.Hash())
151→	if err != nil {
152→		return fmt.Errorf("failed to get local commit: %w", err)
153→	}
154→	localTree, err := localCommit.Tree()
155→	if err != nil {
156→		return fmt.Errorf("failed to get local tree: %w", err)
157→	}
158→
159→	// Get remote (FETCH_HEAD)
160→	fetchHeadRef, err := repo.Reference(plumbing.ReferenceName("FETCH_HEAD"), true)
161→	if err != nil {
162→		return fmt.Errorf("failed to get FETCH_HEAD: %w", err)
163→	}
164→	remoteCommit, err := repo.CommitObject(fetchHeadRef.Hash())
165→	if err != nil {
166→		return fmt.Errorf("failed to get remote commit: %w", err)
167→	}
168→	remoteTree, err := remoteCommit.Tree()
169→	if err != nil {
170→		return fmt.Errorf("failed to get remote tree: %w", err)
171→	}
172→
173→	// Flatten both trees and combine entries
174→	// Session logs have unique cond-* directories, so no conflicts expected
175→	entries := make(map[string]object.TreeEntry)
176→	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
177→		return fmt.Errorf("failed to flatten local tree: %w", err)
178→	}
179→	if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
180→		return fmt.Errorf("failed to flatten remote tree: %w", err)
181→	}
182→
183→	// Build merged tree
184→	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
185→	if err != nil {
186→		return fmt.Errorf("failed to build merged tree: %w", err)
187→	}
188→
189→	// Create merge commit with both parents
190→	mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
191→		[]plumbing.Hash{localRef.Hash(), fetchHeadRef.Hash()},
192→		"Merge remote session logs")
193→	if err != nil {
194→		return fmt.Errorf("failed to create merge commit: %w", err)
195→	}
196→
197→	// Update branch ref
198→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), mergeCommitHash)
199→	if err := repo.Storer.SetReference(newRef); err != nil {
200→		return fmt.Errorf("failed to update branch ref: %w", err)
201→	}
202→
203→	return nil
204→}
