226→// createMergeCommitCommon creates a merge commit with multiple parents.
227→func createMergeCommitCommon(repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
228→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
229→	now := time.Now()
230→	sig := object.Signature{
231→		Name:  authorName,
232→		Email: authorEmail,
233→		When:  now,
234→	}
235→
236→	commit := &object.Commit{
237→		TreeHash:     treeHash,
238→		ParentHashes: parents,
239→		Author:       sig,
240→		Committer:    sig,
241→		Message:      message,
242→	}
243→
244→	obj := repo.Storer.NewEncodedObject()
245→	if err := commit.Encode(obj); err != nil {
246→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
247→	}
248→
249→	hash, err := repo.Storer.SetEncodedObject(obj)
250→	if err != nil {
251→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
252→	}
253→
254→	return hash, nil
255→}
