func newTrailEnableCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "enable",
		Short: "Enable automatic trail creation and pushing",
		Long: `Enable trail auto-creation on session start and pushing the trails branch
on git push. Trails are enabled by default.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runTrailEnable(cmd.OutOrStdout())
		},
	}
	return cmd
}

func runTrailEnable(w io.Writer) error {
	s, err := LoadEntireSettings()
	if err != nil {
		return fmt.Errorf("failed to load settings: %w", err)
	}

	if s.StrategyOptions != nil {
		delete(s.StrategyOptions, "trails")
	}

	if err := SaveEntireSettings(s); err != nil {
		return fmt.Errorf("failed to save settings: %w", err)
	}

	fmt.Fprintln(w, "Trails enabled.")
	return nil
}

func newTrailDisableCmd() *cobra.Command {
	var useProjectSettings bool

	cmd := &cobra.Command{
		Use:   "disable",
		Short: "Disable automatic trail creation and pushing",
		Long: `Disable trail auto-creation on session start and pushing the trails branch
on git push. Existing trails are preserved.

By default, writes to .entire/settings.local.json. Use --project to write to
.entire/settings.json instead.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runTrailDisable(cmd.OutOrStdout(), useProjectSettings)
		},
	}

	cmd.Flags().BoolVar(&useProjectSettings, "project", false, "Write to .entire/settings.json instead of .entire/settings.local.json")
	return cmd
}

func runTrailDisable(w io.Writer, useProjectSettings bool) error {
	s, err := LoadEntireSettings()
	if err != nil {
		return fmt.Errorf("failed to load settings: %w", err)
	}

	if s.StrategyOptions == nil {
		s.StrategyOptions = make(map[string]any)
	}
	s.StrategyOptions["trails"] = false

	if useProjectSettings {
		if err := SaveEntireSettings(s); err != nil {
			return fmt.Errorf("failed to save settings: %w", err)
		}
	} else {
		if err := SaveEntireSettingsLocal(s); err != nil {
			return fmt.Errorf("failed to save local settings: %w", err)
		}
	}

	fmt.Fprintln(w, "Trails disabled.")
	return nil
}

