// IsTrailsDisabled checks if trails are disabled in settings.
// Returns true if strategy_options.trails is explicitly set to false.
// Missing/nil means enabled (default).
func (s *EntireSettings) IsTrailsDisabled() bool {
	if s.StrategyOptions == nil {
		return false
	}
	val, exists := s.StrategyOptions["trails"]
	if !exists {
		return false
	}
	if boolVal, ok := val.(bool); ok {
		return !boolVal // disabled = !trails
	}
	return false
}

// IsTrailsDisabled checks if trails are disabled in settings.
// Returns false by default if settings cannot be loaded or the key is missing.
func IsTrailsDisabled() bool {
	s, err := Load()
	if err != nil {
		return false
	}
	return s.IsTrailsDisabled()
}

